# 1. 首先从 sample_data 字符串中提取所有记录的 “列表字面量”
pattern = re.compile(r"\[([^\]]*?application_id:[^\]]*?)\]", re.DOTALL)
matches = pattern.findall(sample_data)

records = []
for m in matches:
    # 拿到每条记录 — 按逗号分割字符串项，并 strip()
    items = [s.strip().strip("'\"") for s in m.split(",")]
    # 转成 dict
    rec = {}
    for item in items:
        if ':' not in item:
            continue
        k, v = item.split(":", 1)
        rec[k] = v
    records.append(rec)

# 2. 检查重复 application_id
id2idx = defaultdict(list)
for idx, rec in enumerate(records):
    appid = rec.get("application_id")
    if appid:
        id2idx[appid].append(idx)

# 输出重复的
print("=== 检查重复 application_id ===")
found = False
for appid, idxs in id2idx.items():
    if len(idxs) > 1:
        found = True
        print(f"Duplicate application_id: {appid}, indexes/positions: {idxs}")
if not found:
    print("No duplicate application_id found.")
